/**
 * Copies the Meteocons icons WashWise needs into public/meteocons/ (task 1.6).
 * Meteocons ships only animated SVGs, so the static set is generated by stripping the
 * SMIL animation elements, which leaves each icon at its resting frame.
 *
 *   pnpm tsx scripts/vendor-meteocons.ts <path to weather-icons v2.0.0>/production/fill/all <path to LICENSE>
 */
import { copyFileSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'
import { pathToFileURL } from 'node:url'
import { ICON_NAMES } from '../src/features/icons/wmoIcons'

const OUT = 'public/meteocons'

/** Removes <animate>, <animateTransform>, <animateMotion> and <set> (self-closing or paired). */
export function stripAnimation(svg: string): string {
  return svg
    .replace(/<(animate|animateTransform|animateMotion|set)\b[^>]*\/>/g, '')
    .replace(/<(animate|animateTransform|animateMotion|set)\b[^>]*>[\s\S]*?<\/\1>/g, '')
}

function main() {
  const [srcDir, license] = process.argv.slice(2)
  if (!srcDir || !license) {
    console.error('Usage: vendor-meteocons.ts <production/fill/all dir> <LICENSE>')
    process.exit(2)
  }
  mkdirSync(join(OUT, 'animated'), { recursive: true })
  mkdirSync(join(OUT, 'static'), { recursive: true })
  for (const name of ICON_NAMES) {
    const svg = readFileSync(join(srcDir, `${name}.svg`), 'utf8')
    writeFileSync(join(OUT, 'animated', `${name}.svg`), svg)
    writeFileSync(join(OUT, 'static', `${name}.svg`), stripAnimation(svg))
  }
  copyFileSync(license, join(OUT, 'LICENSE'))
  console.log(`✔ ${ICON_NAMES.length} icons → ${OUT}/{animated,static}`)
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) main()
